// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address caller, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);

        vm.assume(caller != address(0));

        vm.deal(address(c), 1 ether);

        vm.deal(caller, 1 ether);

        bool ok;
        vm.prank(caller);
        try c.sendTo(caller, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        address owner = address(this);

        assertTrue(ok == (caller == owner));
    }
}
